    for (const [x, sx] of [[TX0, -1], [TX1, 1]]) for (let k = 0; k < NA; k++) {
      const a0 = Math.PI * k / NA, a1 = Math.PI * (k + 1) / NA, v = (rad, a, w) => TB.v(x, DY + rad * Math.sin(a), ZC + rad * Math.cos(a), sx, 0, 0, a / Math.PI, 1 - w);
      TB.q(v(HW, a0, 0.82), v(HW, a1, 0.82), v(HO, a1, 0.98), v(HO, a0, 0.98));
    }
