    for (const k of Object.keys(A)) if (A[k].i.length) g.add(A[k].mesh(T, M[k]));
    const lp = new T.Vector3((TX0 + TX1) / 2, DY + HW - 0.7, ZC);
    (g.userData.kitLamps = g.userData.kitLamps || []).push({ pos: lp.clone(), color: '#ff4fbf', tag: 'tunnel' });
