      dims: { bowlFloorY: G.BOT, deckY: G.DY, loopInnerTop: +(G.DY + G.HW).toFixed(2), loopOuterTop: +(G.DY + G.HW + G.T).toFixed(2), loopX: [G.TX0, G.TX1], perimeter: +PER.toFixed(2) },
